<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { useRouter } from "vue-router";
import { useAuth } from "@papilio/auth";
import { item, query, request, type Page, type StaffAccess, type StaffRole, type StaffRoleChange } from "@papilio/api";
import { faDate, faNumber } from "@papilio/ui";
import { useI18n } from "vue-i18n";
const props=defineProps<{staff:StaffAccess}>(); const emit=defineEmits<{updated:[StaffAccess]}>(); const auth=useAuth();const router=useRouter();const {t}=useI18n();
const rows=ref<StaffRole[]>([]);const retained=ref<StaffRole[]>([]);const chosen=ref<number[]>([]);const mode=ref("replace");const q=ref("");const page=ref(1);const pages=ref(1);const total=ref(0);const reason=ref("");
const loading=ref(false);const busy=ref(false);const error=ref("");const readError=ref("");const notice=ref("");const history=ref<StaffRoleChange[]>([]);const historyPage=ref(1);const historyPages=ref(1);const historyError=ref("");const historyLoading=ref(false);let readVersion=0;let recordVersion=0;let historyVersion=0;
const selectedRows=computed(()=>chosen.value.map(id=>retained.value.find(role=>role.id===id)));
function message(cause:unknown):string{return cause instanceof Error?cause.message:t("staffRoles.operationFailed");}
function canGrant(role:StaffRole):boolean{const grants=auth.session?.scopes??[];return grants.includes("*")||role.scopes.every(scope=>grants.includes(scope)||grants.includes(`${scope.split(":")[0]}:*`));}
function choose(role:StaffRole,event:Event):void{if(busy.value||(!canGrant(role)&&mode.value!=="remove")||!auth.can("staff","update"))return;if((event.target as HTMLInputElement).checked){chosen.value=[...chosen.value,role.id];if(!retained.value.some(item=>item.id===role.id))retained.value.push(role);}else chosen.value=chosen.value.filter(id=>id!==role.id);}
async function load():Promise<void>{const version=++readVersion;loading.value=true;readError.value="";try{const result=await request<Page<StaffRole>>(`/v1/admin/roles?${query({q:q.value,page:page.value})}`);if(version!==readVersion)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;}catch(cause){if(version===readVersion)readError.value=message(cause);}finally{if(version===readVersion)loading.value=false;}}
async function loadHistory():Promise<void>{const id=props.staff.id;const version=++historyVersion;historyLoading.value=true;historyError.value="";try{const result=await request<Page<StaffRoleChange>>(`/v1/admin/staff/${id}/roles/history?${query({page:historyPage.value})}`);if(version!==historyVersion||props.staff.id!==id)return;history.value=result.data;historyPages.value=result.meta.pager?.total_pages??1;}catch(cause){if(version===historyVersion)historyError.value=message(cause);}finally{if(version===historyVersion)historyLoading.value=false;}}
async function refresh():Promise<void>{if(busy.value)return;busy.value=true;error.value="";const id=props.staff.id;try{const result=await item<StaffAccess>(`/v1/admin/staff/${id}`);if(props.staff.id!==id)return;emit("updated",result);notice.value=t("staffRoles.refreshed");await loadHistory();}catch(cause){error.value=message(cause);}finally{busy.value=false;}}
async function save():Promise<void>{if(busy.value||!auth.can("staff","update"))return;busy.value=true;error.value="";notice.value="";const row=props.staff;try{const result=await item<StaffAccess>(`/v1/admin/staff/${row.id}/roles`,"PUT",{mode:mode.value,role_ids:chosen.value,expected_role_ids:row.role_ids,reason:reason.value});if(props.staff.id!==row.id)return;emit("updated",result);mode.value="replace";chosen.value=[...result.role_ids];reason.value="";notice.value=t("staffRoles.saved");await loadHistory();await auth.restore();if(!auth.session||!auth.can("staff"))await router.push(auth.session?"/":"/login");}catch(cause){error.value=message(cause);}finally{busy.value=false;}}
watch(q,()=>{page.value=1;void load();});
watch(()=>props.staff.id,async()=>{const version=++recordVersion;chosen.value=[...props.staff.role_ids];mode.value="replace";reason.value="";error.value="";notice.value="";retained.value=[];history.value=[];historyPage.value=1;void loadHistory();void load();try{const results=await Promise.all(props.staff.role_ids.map(id=>item<StaffRole>(`/v1/admin/roles/${id}`)));if(version===recordVersion)retained.value=results;}catch(cause){if(version===recordVersion)error.value=message(cause);}},{immediate:true});
</script>
<template>
<section class="stack"><h3>{{t('staffRoles.title',{username:staff.username})}}</h3><p class="hint-box">{{t('staffRoles.effectiveAccess',{scopes:staff.effective_scopes.join(', ')||t('staffRoles.noAccess')})}}</p><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
<form class="form-grid" @submit.prevent="save"><label class="field"><span>{{t('staffRoles.assignmentMethod')}}</span><select :aria-label="t('staffRoles.assignmentMethod')" v-model="mode" :disabled="busy||!auth.can('staff','update')"><option value="replace">{{t('staffRoles.replace')}}</option><option value="add">{{t('staffRoles.add')}}</option><option value="remove">{{t('staffRoles.remove')}}</option></select></label><p>{{t('staffRoles.selected')}}: <span v-for="(role,index) in selectedRows" :key="chosen[index]" class="role-chip">{{role?.title??t('staffRoles.roleId',{id:faNumber(chosen[index]!)})}} <button type="button" :disabled="busy||!auth.can('staff','update')" :aria-label="t('staffRoles.removeRole',{role:role?.title??faNumber(chosen[index]!)})" @click="chosen=chosen.filter(id=>id!==chosen[index])">×</button></span><span v-if="!chosen.length">{{t('staffRoles.noRoles')}}</span></p><label class="field"><span>{{t('staffRoles.search')}}</span><input v-model="q" maxlength="100" :disabled="busy" /></label><p v-if="readError" class="message error">{{readError}}</p><button type="button" class="btn secondary" :disabled="loading||busy" @click="load">{{t('staffRoles.refreshRoles')}}</button><p v-if="loading">{{t('staffRoles.loading')}}</p><label v-for="role in rows" :key="role.id" class="role-option"><input type="checkbox" :checked="chosen.includes(role.id)" :disabled="busy||!auth.can('staff','update')||(!canGrant(role)&&mode!=='remove')" @change="choose(role,$event)" />{{role.title}} · {{role.is_active?t('staffRoles.active'):t('staffRoles.inactive')}}<small dir="ltr">{{role.code}}</small></label><p v-if="!rows.length&&!loading&&!readError">{{t('staffRoles.empty')}}</p><div class="pager"><button type="button" :disabled="page<=1||loading||busy" :aria-label="t('staffRoles.previousPage')" @click="page--;load()">‹</button><span>{{t('staffRoles.pageCount',{page:faNumber(page),total:faNumber(total)})}}</span><button type="button" :disabled="page>=pages||loading||busy" :aria-label="t('staffRoles.nextPage')" @click="page++;load()">›</button></div><label v-if="auth.can('staff','update')" class="field"><span>{{t('staffRoles.changeReason')}}</span><input v-model="reason" minlength="3" maxlength="250" required :disabled="busy" /></label><button v-if="auth.can('staff','update')" class="btn" :disabled="busy||reason.trim().length<3">{{t('staffRoles.save')}}</button><button type="button" class="btn secondary" :disabled="busy" @click="refresh">{{t('staffRoles.refreshRetain')}}</button></form>
<h3>{{t('staffRoles.history')}}</h3><p v-if="historyError" class="message error">{{historyError}}</p><button class="btn secondary" :disabled="historyLoading" @click="loadHistory">{{t('staffRoles.refreshHistory')}}</button><p v-if="historyLoading">{{t('staffRoles.loading')}}</p><div v-for="row in history" :key="row.id" class="hint-box"><p>{{row.reason}} · {{t('staffRoles.staff')}} {{faNumber(row.actor_staff_id)}} · {{faDate(row.created_at)}}</p><p>{{t('staffRoles.previousRoles')}}: {{row.previous_role_ids.map(faNumber).join(', ')||t('staffRoles.noRoles')}}</p><p>{{t('staffRoles.newRoles')}}: {{row.role_ids.map(faNumber).join(', ')||t('staffRoles.noRoles')}}</p></div><div class="pager"><button :disabled="historyPage<=1||historyLoading" :aria-label="t('staffRoles.previousPage')" @click="historyPage--;loadHistory()">‹</button><span>{{faNumber(historyPage)}}</span><button :disabled="historyPage>=historyPages||historyLoading" :aria-label="t('staffRoles.nextPage')" @click="historyPage++;loadHistory()">›</button></div>
</section>
</template>
<style scoped>.role-option{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.role-option input{width:auto;min-height:0}.role-chip{display:inline-flex;align-items:center;gap:6px;margin:4px;padding:4px;border:1px solid var(--line);border-radius:8px}.role-chip button{padding:0 5px;min-height:24px}.role-option small{color:var(--muted)}</style>
